$ErrorActionPreference='Stop'; $root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..')); $dotnet=Join-Path $root 'Logs/BackendSdk/dotnet.exe'; $project=Join-Path $root 'Backend/TankDraft.PlayFabIdentityChecks/TankDraft.PlayFabIdentityChecks.csproj'; Push-Location (Join-Path $root 'Backend'); try { & $dotnet restore $project --configfile NuGet.Config --locked-mode; if($LASTEXITCODE){throw 'Locked PlayFab identity restore failed.'}; & $dotnet run --project $project --no-restore -c Release; if($LASTEXITCODE){throw 'PlayFab identity checks failed.'} } finally {Pop-Location}
